 31	// The module clock is pinned to the time the host test case travels to, so a work item's
 32	// due time, a lease and the scheduler's own clock all agree.
 33	const ADMISSION_NOW = '2024-01-01 00:00:00';
 34	const ADMISSION_DAY = '2024-01-01';
