 40	function bindAdmissionClock(string $now): void
 41	{
 42	    app()->bind(AiClock::class, fn (): FixtureAiClock => app()->makeWith(FixtureAiClock::class, [
 43	        'now' => CarbonImmutable::parse($now),
 44	    ]));
 45	}
