 47	function admissionProfile(int $playerId): AiProfile
 48	{
 49	    return AiProfile::create([
 50	        'player_id' => $playerId,
 51	        'archetype' => AiArchetype::Miner,
 52	        'skill_band' => AiSkillBand::Standard,
 53	        'random_seed' => 42,
 54	        'enabled' => true,
