 58	function admissionWorkItem(int $playerId, AiWorkKind $kind, string $suffix, AiWorkState $state = AiWorkState::Pending, CarbonImmutable|null $leaseUntil = null): AiWorkItem
 59	{
 60	    return AiWorkItem::create([
 61	        'player_id' => $playerId,
 62	        'kind' => $kind,
 63	        'due_at' => CarbonImmutable::parse(ADMISSION_NOW),
 64	        'idempotency_key' => 'admission:' . $suffix . ':' . $playerId,
 65	        'state' => $state,
 66	        'lease_token' => $state === AiWorkState::Leased ? 'admission-lease-' . $suffix : null,
 67	        'lease_until' => $leaseUntil,
 68	    ]);
 69	}
