 71	function admissionStopCount(AiStopReason $reason, string $day = ADMISSION_DAY): int
 72	{
 73	    return (int) AiStopCounter::query()
 74	        ->where('reason', $reason->value)
 75	        ->where('observed_on', $day)
 76	        ->sum('occurrences');
 77	}
