 79	/**
 80	 * @return array<string, mixed>
 81	 */
 82	function admissionStopContext(AiStopReason $reason, string $day = ADMISSION_DAY): array
 83	{
 84	    return AiStopCounter::query()
 85	        ->where('reason', $reason->value)
 86	        ->where('observed_on', $day)
 87	        ->sole()
 88	        ->last_context ?? [];
