  3	namespace Modules\AI\Jobs;
  4	
  5	use Carbon\CarbonImmutable;
  6	use Illuminate\Contracts\Queue\ShouldQueue;
  7	use Illuminate\Foundation\Queue\Queueable;
  8	use Illuminate\Support\Facades\Cache;
  9	use Illuminate\Support\Facades\DB;
 10	use Illuminate\Support\Facades\Log;
 11	use Illuminate\Support\Str;
 12	use Modules\AI\Actions\ExecuteAiIntentAction;
 13	use Modules\AI\Actions\ResolveAiAdmissionAction;
 14	use Modules\AI\Contracts\RunAiSession;
 15	use Modules\AI\Enums\AiActionReceiptResultKey;
 16	use Modules\AI\Enums\AiQueueActionReason;
 17	use Modules\AI\Enums\AiQueueName;
 18	use Modules\AI\Enums\AiReceiptState;
 19	use Modules\AI\Enums\AiWorkKind;
 20	use Modules\AI\Enums\AiWorkState;
 21	use Modules\AI\Domain\Routine\SessionPlanner;
 22	use Modules\AI\Models\AiActionReceipt;
 23	use Modules\AI\Models\AiProfile;
 24	use Modules\AI\Models\AiSchedule;
 25	use Modules\AI\Models\AiWorkItem;
 26	use OGame\Models\Planet;
 27	use Throwable;
 28	
 29	class ProcessAiWork implements ShouldQueue
 30	{
 31	    use Queueable;
 32	
 33	    public int $tries = 3;
 34	
 35	    /** Bounds a poison work item; retryLease() owns the work-item attempt cap. */
 36	    public int $maxExceptions = 3;
 37	
 38	    /**
 39	     * Leave margin below the module's Horizon timeout so a worker is not force-killed
 40	     * mid-decision. The grand run raises both values for hybrid driver contention.
 41	     */
 42	    public int $timeout;
 43	
 44	    private const PAYLOAD_PLANET_ID = 'planet_id';
 45	
 46	    public function __construct(public int $workItemId)
 47	    {
 48	        $this->timeout = max(1, (int) config('ai.horizon.supervisors.supervisor-ai.timeout', 30) - 5);
 49	
 50	        // Deterministic AI work has its own module-owned Horizon lane so AI volume
 51	        // cannot starve the general or fleet lanes.
 52	        $this->onQueue(AiQueueName::Ai->value);
 53	    }
 54	
 55	    /** @return list<string> */
 56	    public function tags(): array
 57	    {
 58	        return ['ai', 'ai:work', 'ai:work-item:' . $this->workItemId];
 59	    }
 60	
 61	    public function failed(Throwable $exception): void
 62	    {
 63	        Log::error('AI work item failed after all queue attempts', [
 64	            'work_item_id' => $this->workItemId,
 65	            'error' => $exception->getMessage(),
 66	        ]);
 67	
 68	        $this->scheduleSessionRecovery();
 69	    }
 70	
 71	    public function handle(): void
 72	    {
 73	        // A switch that is off stops new decisions without discarding the work: the item stays
 74	        // pending and the first pass after it is switched back on picks it up again.
 75	        if (!app(ResolveAiAdmissionAction::class)->forWorkItem()->allowed) {
 76	            return;
 77	        }
 78	
 79	        $leaseToken = (string) Str::uuid();
 80	        // Claim before side effects. Every terminal update checks this token so
 81	        // a slow worker cannot complete work leased again by another worker.
 82	        $workItem = $this->claimDueWork($leaseToken);
 83	
 84	        if ($workItem === null) {
 85	            return;
 86	        }
 87	
 88	        $lock = Cache::lock('ai:player:' . $workItem->player_id, 300);
 89	        if (!$lock->get()) {
 90	            $this->retryContendedLease($workItem, $leaseToken);
 91	
 92	            return;
 93	        }
 94	
 95	        try {
 96	            $profile = AiProfile::query()->where('player_id', $workItem->player_id)->where('enabled', true)->first();
 97	            if ($profile === null) {
 98	                $this->completeLease($workItem, $leaseToken);
 99	
100	                return;
101	            }
102	
103	            if ($workItem->kind === AiWorkKind::RunSession) {
104	                $this->runClaimedSession($profile, $workItem, $leaseToken);
105	
106	                return;
107	            }
108	
109	            $this->queueClaimedIntent($profile, $workItem, $leaseToken);
110	        } catch (Throwable $exception) {
111	            $this->retryLease($workItem, $leaseToken);
112	
113	            throw $exception;
114	        } finally {
115	            $lock->release();
116	        }
117	    }
118	
119	    private function claimDueWork(string $leaseToken): AiWorkItem|null
120	    {
121	        return DB::transaction(function () use ($leaseToken): AiWorkItem|null {
122	            /** @var AiWorkItem|null $workItem */
123	            $workItem = AiWorkItem::query()->lockForUpdate()->find($this->workItemId);
124	            if ($workItem === null || !$this->isClaimable($workItem) || !$this->dueForAccount($workItem)) {
125	                return null;
126	            }
127	
128	            $workItem->update([
129	                'state' => AiWorkState::Leased,
130	                'lease_token' => $leaseToken,
131	                'lease_until' => now()->addMinutes(5),
132	                'attempts' => $workItem->attempts + 1,
133	            ]);
134	
135	            return $workItem->fresh();
136	        });
137	    }
138	
139	    private function acceleratedSession(AiWorkItem $workItem): bool
140	    {
141	        if ($workItem->kind !== AiWorkKind::RunSession || (int) config('ai.population.session_interval_seconds', 0) <= 0) {
142	            return false;
143	        }
144	
145	        // Acceleration shortens the waits, not the night: a dark-period session keeps its due time.
146	        $profile = $this->workProfile($workItem);
147	
148	        return $profile === null || app(SessionPlanner::class)->isAwake($profile, now()->toImmutable());
149	    }
150	
151	    /**
152	     * Whether the account's own clock has come for this item.
153	     *
154	     * An accelerated session is claimable the moment its account is awake (that is what shortens the
155	     * waits), and any item is claimable once its own due time has passed. A session is the exception:
156	     * the one a session leaves behind is due seconds later, so a worker that is minutes behind finds
157	     * every session in the cohort overdue, and an overdue session used to be claimable at any hour --
158	     * which put the whole population online through its own night (AUTH_UPTIME). A session therefore
159	     * keeps the hour it was scheduled for: only the night session the routine placed in the dark
160	     * period itself, the reaction wake to an attack landing then, is run at night.
161	     */
162	    private function dueForAccount(AiWorkItem $workItem): bool
163	    {
164	        if ($workItem->due_at->isFuture()) {
165	            return $this->acceleratedSession($workItem);
166	        }
167	
168	        return $workItem->kind !== AiWorkKind::RunSession || $this->sessionKeepsItsOwnHour($workItem);
169	    }
170	
171	    /**
172	     * A session scheduled inside the account's waking window waits for its waking day however late the
173	     * worker is; one scheduled inside the dark period is a wake the routine meant to take.
174	     */
175	    private function sessionKeepsItsOwnHour(AiWorkItem $workItem): bool
176	    {
177	        $profile = $this->workProfile($workItem);
178	        if ($profile === null) {
179	            return true;
180	        }
181	
182	        $planner = app(SessionPlanner::class);
183	
184	        // Only a login the routine itself placed in the night is taken then. One a retry moved into the
185	        // dark period is a login the account owed its day, and taking it there is the night login the
186	        // host counts (AUTH_UPTIME).
187	        return $planner->isAwake($profile, now()->toImmutable())
188	            || ($workItem->state === AiWorkState::Pending && !$planner->isAwake($profile, $workItem->due_at->toImmutable()));
189	    }
190	
191	    /**
192	     * When a retried item comes back.
193	     *
194	     * A login keeps the account's day: a retry that would land in the account's dark period takes the
195	     * account's next waking login instead, exactly as a failed session already does. A build order, a
196	     * raid or a transfer is not a login and keeps its own retry.
197	     */
198	    private function retryDueAt(AiWorkItem $workItem, CarbonImmutable $retryAt): CarbonImmutable
199	    {
200	        if ($workItem->kind !== AiWorkKind::RunSession) {
201	            return $retryAt;
202	        }
203	
204	        $profile = $this->workProfile($workItem);
205	        $planner = app(SessionPlanner::class);
206	
207	        if ($profile === null || $planner->isAwake($profile, $retryAt)) {
208	            return $retryAt;
209	        }
210	
211	        return $planner->plan($profile, now()->toImmutable(), (int) $workItem->schedule_generation)->nextDueAt;
212	    }
213	
214	    private function workProfile(AiWorkItem $workItem): AiProfile|null
215	    {
216	        return AiProfile::query()->where('player_id', $workItem->player_id)->first();
217	    }
218	
219	    private function isClaimable(AiWorkItem $workItem): bool
220	    {
221	        if (in_array($workItem->state, [AiWorkState::Pending, AiWorkState::Retry], true)) {
222	            return true;
223	        }
224	
225	        // A worker killed mid-handle leaves the item Leased; reclaim it once the lease
226	        // expires so a queue retry or the scheduler can finish the work instead of the
227	        // item staying stuck forever.
228	        return $workItem->state === AiWorkState::Leased
229	            && $workItem->lease_until !== null
230	            && $workItem->lease_until->isPast();
231	    }
232	
233	    private function runClaimedSession(AiProfile $profile, AiWorkItem $workItem, string $leaseToken): void
234	    {
235	        app(RunAiSession::class)->handle($profile, $workItem);
236	        $this->completeLease($workItem, $leaseToken);
237	    }
238	
239	    private function queueClaimedIntent(AiProfile $profile, AiWorkItem $workItem, string $leaseToken): void
240	    {
241	        // The action cap bounds what a session may touch, not what it may think: at zero the
242	        // session already decided and scheduled, so this pass closes its lease and acts on
243	        // nothing.
244	        if (!app(ResolveAiAdmissionAction::class)->forAction()->allowed) {
245	            $this->completeLease($workItem, $leaseToken);
246	
247	            return;
248	        }
249	
250	        $receipt = AiActionReceipt::query()->firstOrCreate(
251	            ['idempotency_key' => $workItem->idempotency_key],
252	            [
253	                'player_id' => $workItem->player_id,
254	                'action_type' => $workItem->kind->actionType(),
255	                'state' => AiReceiptState::Processing,
256	            ],
257	        );
258	        if (in_array($receipt->state, [AiReceiptState::Accepted, AiReceiptState::Completed, AiReceiptState::Rejected], true)) {
259	            $this->completeLease($workItem, $leaseToken);
260	
261	            return;
262	        }
263	
264	        $planetId = $this->ownedPlanetIdFor($workItem);
265	        if ($planetId === 0) {
266	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::NoOwnedPlanet->value]]);
267	            $this->completeLease($workItem, $leaseToken);
268	
269	            return;
270	        }
271	
272	        // An intent that names a body this account does not own is not this account's to act on, and
273	        // re-planning it onto a different one would silently change what the session decided.
274	        if (!Planet::query()->whereKey($planetId)->where('user_id', $workItem->player_id)->exists()) {
275	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::PlanetNotOwned->value]]);
276	            $this->completeLease($workItem, $leaseToken);
277	
278	            return;
279	        }
280	
281	        [$result, $decision, $actedPlanetId] = app(ExecuteAiIntentAction::class)->execute($workItem, $planetId);
282	        if ($result === null) {
283	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::NothingQueueable->value]]);
