289	        $receipt->update([
290	            'state' => $result->successful ? AiReceiptState::Accepted : AiReceiptState::Rejected,
291	            'result' => [
292	                AiActionReceiptResultKey::QueueId->value => $result->queueId,
293	                AiActionReceiptResultKey::Reason->value => $result->reason,
294	                AiActionReceiptResultKey::Decision->value => $decision,
295	                AiActionReceiptResultKey::PlanetId->value => $actedPlanetId,
