306	    private function completeLease(AiWorkItem $workItem, string $leaseToken): void
307	    {
308	        AiWorkItem::query()->whereKey($workItem->id)->where('lease_token', $leaseToken)->update([
309	            'state' => AiWorkState::Completed, 'lease_token' => null, 'lease_until' => null,
310	        ]);
311	    }
