313	    private function retryLease(AiWorkItem $workItem, string $leaseToken): void
314	    {
315	        $failed = $workItem->attempts >= $this->tries;
316	
317	        AiWorkItem::query()->whereKey($workItem->id)->where('lease_token', $leaseToken)->update([
318	            'state' => $failed ? AiWorkState::Failed : AiWorkState::Retry,
319	            'due_at' => $this->retryDueAt($workItem, now()->addMinute()->toImmutable()),
320	            'lease_token' => null,
321	            'lease_until' => null,
322	        ]);
323	
324	        if ($failed) {
325	            $this->scheduleSessionRecovery();
326	        }
327	    }
