330	    {
331	        AiWorkItem::query()->whereKey($workItem->id)->where('lease_token', $leaseToken)->update([
332	            'state' => AiWorkState::Retry,
333	            'due_at' => $this->retryDueAt($workItem, now()->addSeconds(5)->toImmutable()),
334	            'attempts' => 0,
335	            'lease_token' => null,
336	            'lease_until' => null,
337	        ]);
338	    }
339	
340	    private function scheduleSessionRecovery(): void
341	    {
342	        DB::transaction(function (): void {
343	            $workItem = AiWorkItem::query()
344	                ->lockForUpdate()
345	                ->find($this->workItemId);
346	
347	            if ($workItem === null || $workItem->kind !== AiWorkKind::RunSession || $workItem->state !== AiWorkState::Failed) {
348	                return;
349	            }
350	
351	            $schedule = AiSchedule::query()
352	                ->where('player_id', $workItem->player_id)
353	                ->lockForUpdate()
354	                ->first();
355	
356	            if ($schedule === null) {
357	                return;
358	            }
359	
360	            if ($schedule->generation > (int) $workItem->schedule_generation) {
361	                return;
362	            }
363	
364	            $nextGeneration = max($schedule->generation, (int) $workItem->schedule_generation) + 1;
365	            $nextDueAt = now()->addMinute();
366	
367	            // A failed session is retried a minute on only while the account is awake: a retry in the
368	            // dark period would put the account on at an hour it sleeps (AUTH_UPTIME), so it takes the
369	            // routine's next wake instead. An accelerated cohort keeps the minute: a failure there would
370	            // otherwise park the account for hours, and failures are rare enough not to fill the night.
371	            $profile = AiProfile::query()->where('player_id', $workItem->player_id)->first();
372	            if ((int) config('ai.population.session_interval_seconds', 0) <= 0 && $profile !== null && !app(SessionPlanner::class)->isAwake($profile, $nextDueAt->toImmutable())) {
373	                $nextDueAt = app(SessionPlanner::class)->plan($profile, now()->toImmutable(), $schedule->generation)->nextDueAt;
374	            }
375	
376	            $schedule->update([
377	                'next_due_at' => $nextDueAt,
378	                'generation' => $nextGeneration,
379	            ]);
380	
381	            AiWorkItem::query()->firstOrCreate(
382	                ['idempotency_key' => 'session:' . $workItem->player_id . ':' . $nextGeneration],
383	                [
384	                    'player_id' => $workItem->player_id,
385	                    'kind' => AiWorkKind::RunSession,
386	                    'due_at' => $nextDueAt,
387	                    'schedule_generation' => $nextGeneration,
388	                    'state' => AiWorkState::Pending,
389	                ],
390	            );
391	        });
392	    }
