 14	/**
 15	 * Decides how much work the module may start right now, and records why it stopped.
 16	 *
 17	 * Every cap lives here rather than at its call sites. The scheduler, the session job and the
 18	 * action path all ask the same question, and a limit one caller enforced while another forgot
 19	 * would read in a pilot report as an idle population rather than a capped one. The refusal is
 20	 * recorded together with the decision, because a stop nobody wrote down looks the same as no
 21	 * stop at all.
 22	 *
 23	 * The size caps are checked against what the module can see rather than what it enforces by
 24	 * deleting anything: exceeding the profile cap stops new work and leaves the decision of which
 25	 * accounts to remove to the operator.
 26	 */
 27	class ResolveAiAdmissionAction
 28	{
 29	    public function __construct(private readonly AiClock $clock)
 30	    {
 31	    }
 32	
 33	    /**
 34	     * @param int $requestedLimit the batch the caller would like to dispatch
 35	     */
 36	    public function forDispatch(int $requestedLimit): AiAdmission
 37	    {
 38	        if (!$this->staffSwitchAllowsWork()) {
 39	            return $this->stopped(AiStopReason::StaffSwitch, ['pass' => 'dispatch']);
 40	        }
 41	
 42	        $profileCap = app(AiRuntimeSettings::class)->profileCap();
 43	        $enabledProfiles = AiProfile::query()->where('enabled', true)->count();
 44	
 45	        if ($profileCap > 0 && $enabledProfiles > $profileCap) {
 46	            return $this->stopped(AiStopReason::ProfileCap, ['profiles' => $enabledProfiles, 'cap' => $profileCap]);
 47	        }
 48	
 49	        $sessionCap = app(AiRuntimeSettings::class)->activeSessionCap();
 50	        $activeSessions = $this->activeSessionCount();
 51	
 52	        if ($sessionCap > 0 && $activeSessions >= $sessionCap) {
 53	            return $this->stopped(AiStopReason::ActiveSessionCap, ['active_sessions' => $activeSessions, 'cap' => $sessionCap]);
 54	        }
 55	
 56	        $batchSize = app(AiRuntimeSettings::class)->dispatchBatchSize();
 57	
 58	        if ($batchSize < $requestedLimit) {
 59	            return $this->limited($batchSize, AiStopReason::DispatchLimit, ['requested' => $requestedLimit, 'cap' => $batchSize]);
 60	        }
 61	
 62	        return $this->allowed($requestedLimit);
 63	    }
 64	
 65	    /**
 66	     * Whether a claimed session may run. The lease is taken before this question is asked, so a
 67	     * refusal leaves the work item pending for the first pass after the switch returns.
 68	     */
 69	    public function forWorkItem(): AiAdmission
 70	    {
 71	        if (!$this->staffSwitchAllowsWork()) {
 72	            return $this->stopped(AiStopReason::StaffSwitch, ['pass' => 'work_item']);
 73	        }
 74	
 75	        return $this->allowed(1);
 76	    }
 77	
 78	    /**
 79	     * Whether a session may queue a game action. The cap applies to the action, not to the
 80	     * account: at zero an AI still decides, records its intent and schedules its next session,
 81	     * which is the setting a staff member wants while investigating something.
 82	     */
 83	    public function forAction(): AiAdmission
 84	    {
 85	        if (!$this->staffSwitchAllowsWork()) {
 86	            return $this->stopped(AiStopReason::StaffSwitch, ['pass' => 'action']);
 87	        }
 88	
 89	        $actionCap = app(AiRuntimeSettings::class)->sessionActionCap();
 90	
 91	        if ($actionCap < 1) {
 92	            return $this->stopped(AiStopReason::SessionActionCap, ['cap' => $actionCap]);
 93	        }
 94	
 95	        return $this->allowed($actionCap);
 96	    }
 97	
 98	    /**
 99	     * Work in flight is what the active-session cap counts: a work item that is leased now is a
100	     * session a worker is running, and one whose lease expired is work the scheduler will retry
101	     * rather than work that is running.
102	     */
103	    private function activeSessionCount(): int
104	    {
105	        return AiWorkItem::query()
106	            ->where('state', AiWorkState::Leased)
107	            ->where('lease_until', '>', $this->clock->now())
108	            ->count();
109	    }
