124	     */
125	    private function stopped(AiStopReason $reason, array $context): AiAdmission
126	    {
127	        app(RecordAiStopReasonAction::class)->handle($reason, $context);
128	
129	        return $this->admission(false, 0, $reason, $context);
130	    }
131	
132	    /**
133	     * @param array<string, mixed> $context
134	     */
135	    private function limited(int $limit, AiStopReason $reason, array $context): AiAdmission
136	    {
137	        app(RecordAiStopReasonAction::class)->handle($reason, $context);
138	
139	        return $this->admission(true, $limit, $reason, $context);
140	    }
141	
142	    private function allowed(int $limit): AiAdmission
143	    {
144	        return $this->admission(true, $limit, null, []);
145	    }
