 5	use Illuminate\Console\Attributes\Description;
 6	use Illuminate\Console\Attributes\Signature;
 7	use Illuminate\Console\Command;
 8	use Illuminate\Database\Eloquent\Builder;
 9	use Modules\AI\Actions\ResolveAiAdmissionAction;
10	use Modules\AI\Enums\AiWorkKind;
11	use Modules\AI\Enums\AiWorkState;
12	use Modules\AI\Jobs\ProcessAiWork;
13	use Modules\AI\Models\AiWorkItem;
14	use Modules\AI\Support\AiRuntimeSettings;
15	
16	#[Description('Dispatch due AI work items without making decisions.')]
17	#[Signature('ai:run-due-work {--limit=}')]
18	class RunDueAiWork extends Command
19	{
20	    public function handle(): int
21	    {
22	        // No flag means the configured batch: the scheduler fires once a minute, so a fixed 100 starved a cohort larger than that.
23	        $requestedLimit = max(1, (int) ($this->option('limit') ?? app(AiRuntimeSettings::class)->dispatchBatchSize()));
24	        $admission = app(ResolveAiAdmissionAction::class)->forDispatch($requestedLimit);
25	
26	        // A refusal is a state an operator chose, not a failure of this command, so the pass
27	        // reports it and succeeds; the reason is what the admin page and the pilot report read.
28	        if (!$admission->allowed) {
29	            $this->warn('AI work is not admitted: ' . $admission->stopReason?->value);
30	
31	            return self::SUCCESS;
32	        }
33	
34	        // This pass is the only thing that ever admits work, so a lease left behind by a worker the
35	        // queue killed mid-handle (a timeout, an OOM) has to be admitted here too: with its job gone
36	        // no retry will arrive, and ProcessAiWork's own reclaim would never be reached, stranding the
37	        // item Leased forever. A live lease cannot match, because a worker cannot outlive its lease.
38	        $work = AiWorkItem::query()
39	            ->where(function (Builder $query): void {
40	                $query->whereIn('state', [AiWorkState::Pending, AiWorkState::Retry])
41	                    ->orWhere(function (Builder $stranded): void {
42	                        $stranded->where('state', AiWorkState::Leased)
43	                            ->where('lease_until', '<', now());
44	                    });
45	            })
46	            // Orders already due go before sessions: an accelerated session is claimable whenever it is
47	            // dispatched, so by due time alone the batch fills with sessions and the building, transfer
48	            // and save orders they scheduled wait behind them.
49	            ->orderByRaw('kind = ? asc', [AiWorkKind::RunSession->value])
50	            ->oldest('due_at')
51	            ->limit($admission->limit);
52	
53	        if ((int) config('ai.population.session_interval_seconds', 0) <= 0) {
54	            $work->where('due_at', '<=', now());
55	        }
56	        if ((int) config('ai.population.session_interval_seconds', 0) > 0) {
57	            $work->where(fn (Builder $due) => $due->where('kind', AiWorkKind::RunSession->value)->orWhere('due_at', '<=', now()));
58	        }
59	
60	        $work->pluck('id')
61	            ->each(static fn (int $workItemId) => ProcessAiWork::dispatch($workItemId));
62	
63	        return self::SUCCESS;
64	    }
65	}

